 void iconChecks()throws Exception{
  ui(()->{
   for(boolean light:new boolean[]{false,true}){store.prefs.edit().putBoolean("ten_light",light).putBoolean("ten_apps_dark",!light).commit();home.applyTenAppearance();for(String kind:new String[]{"files","file-explorer","settings","calculator","calendar","recycle","recycle-full","pictures-app","browser","notes","taskmanager","documentfile"})for(int size:new int[]{32,128}){android.graphics.drawable.Drawable source=ElevenIconAssets.drawable(home,kind);check(source!=null,"Pristine source is available: "+kind);AeroIcon view=new AeroIcon(home,kind);view.measure(View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY));view.layout(0,0,size,size);TenAppearance.apply(view);check(iconPixels(view,source,size),"Rendered icon uses the untinted source at "+size+" px in "+(light?"light":"dark")+": "+kind);}}
   check(ElevenIconAssets.resource("orb",true)==0&&ElevenIconAssets.resource("nota",false)==0,"Nth branding is not replaced by Microsoft artwork");
   TenStyle.Glyph taskView=new TenStyle.Glyph(home,"taskview",Color.RED);for(boolean light:new boolean[]{true,false}){store.prefs.edit().putBoolean("ten_light",light).commit();taskView.measure(View.MeasureSpec.makeMeasureSpec(32,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(32,View.MeasureSpec.EXACTLY));taskView.layout(0,0,32,32);check(iconPixels(taskView,ElevenIconAssets.drawable(home,"taskview",light),32),"Task View swaps to supplied "+(light?"light":"dark")+" artwork");}store.prefs.edit().putBoolean("ten_light",false).putBoolean("ten_apps_dark",true).commit();home.applyTenAppearance();
  });
  final View[] overlay={null};ui(()->{LinearLayout sheet=Aero.column(home);sheet.setPadding(Aero.dp(home,12),Aero.dp(home,12),Aero.dp(home,12),Aero.dp(home,12));sheet.setBackgroundColor(TenStyle.surface(home));sheet.setContentDescription("Pristine icon rendering sheet");TextView title=Aero.text(home,"Windows 11 source icons",18,TenStyle.text(home));sheet.addView(title);GridLayout grid=new GridLayout(home);grid.setColumnCount(4);String[][] icons={{"file-explorer","Explorer"},{"files","Folder"},{"settings","Settings"},{"recycle","Recycle Bin"},{"calculator","Calculator"},{"calendar","Calendar"},{"pictures-app","Photos"},{"taskmanager","Task Manager"},{"documents","Documents"},{"downloads","Downloads"},{"pictures","Pictures"},{"music","Music"},{"browser","Browser"},{"notes","Notepad"},{"sticky","Sticky Notes"},{"terminal","Terminal"}};for(int i=0;i<icons.length;i++){LinearLayout cell=Aero.column(home);cell.setGravity(Gravity.CENTER);cell.addView(new AeroIcon(home,icons[i][0]),new LinearLayout.LayoutParams(Aero.dp(home,48),Aero.dp(home,48)));TextView label=Aero.text(home,icons[i][1],11,TenStyle.text(home));label.setGravity(Gravity.CENTER);cell.addView(label);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/4),GridLayout.spec(i%4,1f));p.width=0;p.height=Aero.dp(home,90);grid.addView(cell,p);}sheet.addView(grid,new LinearLayout.LayoutParams(-1,-2));overlay[0]=sheet;((ViewGroup)root).addView(sheet,new ViewGroup.LayoutParams(-1,-1));sheet.bringToFront();});shot("eleven-pristine-icons");ui(()->((ViewGroup)root).removeView(overlay[0]));
 }
 boolean iconPixels(View view,android.graphics.drawable.Drawable source,int size){Bitmap actual=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888),expected=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);try{view.draw(new Canvas(actual));source.setBounds(0,0,size,size);source.draw(new Canvas(expected));int[] a=new int[size*size],b=new int[size*size];actual.getPixels(a,0,size,0,0,size,size);expected.getPixels(b,0,size,0,0,size,size);return java.util.Arrays.equals(a,b);}finally{actual.recycle();expected.recycle();}}
 boolean consumesBlankTap(View view){long now=SystemClock.uptimeMillis();float y=view instanceof DesktopWindow?view.getHeight()/2f:0;MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,0,y,0),up=MotionEvent.obtain(now,now+40,MotionEvent.ACTION_UP,0,y,0);try{return view.dispatchTouchEvent(down)&&view.dispatchTouchEvent(up);}finally{down.recycle();up.recycle();}}
 void check(boolean yes,String message){checks++;if(!yes)throw new AssertionError(message);}
 void ui(Runnable task)throws Exception{Bundle progress=new Bundle();progress.putString("stream","Eleven: UI block after "+checks+" checks\n");sendStatus(0,progress);FutureTask<Void> f=new FutureTask<>(task,null);home.runOnUiThread(f);f.get(30,TimeUnit.SECONDS);}
 void shot(String name)throws Exception{Bundle progress=new Bundle();progress.putString("stream","Eleven: capture "+name+" after "+checks+" checks\n");sendStatus(0,progress);waitForIdleSync();SystemClock.sleep(350);ui(()->{Bitmap view=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(view));try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+"-view.png"))){view.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{view.recycle();}});Bitmap b=getUiAutomation().takeScreenshot();if(b!=null){try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}}
